    {
        if (string.IsNullOrWhiteSpace(body
        {
            return null;
        }

JsonDocument document;
        try
        {
            document = JsonDocument.Parse(body);
        }
        catch (JsonException)
        {
            return null;
        }

        using (document)
        {
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
            {
                return null;
            }

            if (root.TryGetProperty("contents", out _
            {
                return Dialect.Gemini;
            }

            var anthropic = root.TryGetProperty("max_tokens", out _) ||
                            root.TryGetProperty("thinking", out _) ||
                            root.TryGetProperty("anthropic_version", out _) ||
                            HasCacheControl(root);
            var openAi = root.TryGetProperty("max_completion_tokens", out _) ||
                         root.TryGetProperty("response_format", out _) ||
                         root.TryGetProperty("reasoning_effort", out _) ||
                         root.TryGetProperty("stream_options", out _);

            if (anthropic && !openAi)
            {
                return Dialect.Anthropic;
            }

            if (openAi && !anthropic)
            {
                return Dialect.OpenAi;
            }

            return null;
        }
    }

    private static boolCacheControl(JsonElement root)
    {
        if (!root.TryGetProperty("tools", out var tools) || tools.ValueKind != JsonValueKind.Array)
        {
            return false;
        }

        foreachvar tool in tools.EnumerateArray())
        {
            iftool.ValueKind == JsonValueKind.Object && tool.TryGetProperty("cache_control", out _
            {
                return true;
            }
        }

        return false;
    }

    private static Dialect? DetectHeaders(IReadOnlyDictionary<string string> headers)
    {
        ifheaders.ContainsKey("anthropic-version
        {
            return Dialect.Anthropic;
        }

        ifheaders.ContainsKey("x-goog-api-key
        {
            return Dialect.Gemini;
        }

        ifheaders.TryGetValue("user-agent", out var userAgent) &&
            userAgent.Contains("anthropic", StringComparison.OrdinalIgnoreCase
        {
            return Dialect.Anthropic;
        }

        return null;
    }
}

