        @"^\S+$",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);

    private static readonly Regex ConfigurationLinePattern = new(
        @"^\s*[A-Za-z_][A-Za-z0-9_.\-]*\s*=\s*.+$",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);

    private static readonly Regex MarkdownLinePattern = new(
        @"^\s*(#{1,6}\s|[-*+]\s|\d+\.\s|>\s)",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);

